import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Publish your documentation site","description":"","frontmatter":{"docLocale":"en","counterpart":"/getting-started/publish-docs","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/getting-started/publish-docs.md","filePath":"en/getting-started/publish-docs.md"}'),n={name:"en/getting-started/publish-docs.md"};function o(r,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="publish-your-documentation-site" tabindex="-1">Publish your documentation site <a class="header-anchor" href="#publish-your-documentation-site" aria-label="Permalink to &quot;Publish your documentation site&quot;">​</a></h1><p>Publish a checked bilingual static build to your own GitHub Pages. Repository Markdown, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/site.json" target="_blank" rel="noreferrer">site.json</a> and real code are canonical; generated sources and dist do not belong in the source branch. See <a href="./../guides/documentation">Maintain documentation</a> for authoring and registration.</p><p>You need push access, plus repository administration access for initial setup. Requesting Pages builds requires an installed, authenticated GitHub CLI. Run commands from the repository root. Publishing writes static artifacts to remote <code>gh-pages</code>.</p><h2 id="prepare-public-source-and-build" tabindex="-1">Prepare public source and build <a class="header-anchor" href="#prepare-public-source-and-build" aria-label="Permalink to &quot;Prepare public source and build&quot;">​</a></h2><p>Confirm <code>origin</code> points to your GitHub repository and change <code>docs/site.json.repository</code> to <code>owner/repository</code>. Register bilingual pages, commit/push the source, then build:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>The footer SHA identifies the source revision referenced by the build; it does not establish that every example command passed on that revision. Published content must exist in the corresponding commit. Rebuild after committing so source links resolve on GitHub.</p><p>The repository name determines the default Pages prefix. Set a custom path at build time:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DOCS_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/my-saas/</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>Base must match the actual deployment path. Chapters, language switching, assets and search share it; do not repair paths by editing dist.</p><h2 id="publish-and-configure-pages-once" tabindex="-1">Publish and configure Pages once <a class="header-anchor" href="#publish-and-configure-pages-once" aria-label="Permalink to &quot;Publish and configure Pages once&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/publish-docs.mjs" target="_blank" rel="noreferrer">publish script</a> verifies the artifact repository/source revision against publish inputs, commits and pushes artifacts to independent <code>gh-pages</code>, and leaves the source branch and index unchanged. Identical artifacts do not create unnecessary commits.</p><p>In GitHub <strong>Settings → Pages → Build and deployment</strong>, choose <strong>Deploy from a branch</strong>, branch <code>gh-pages</code>, directory <code>/ (root)</code>, and save. Whether Pages supports the repository&#39;s visibility depends on the account plan.</p><p>Then request and verify the online build:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --request-build</span></span></code></pre></div><p>The command checks Pages configuration, explicitly requests a build, confirms its artifact commit and reads the live homepage&#39;s source SHA. It fails if this does not succeed within five minutes. A pushed branch does not establish that the page is live.</p><h2 id="subsequent-automatic-publication" tabindex="-1">Subsequent automatic publication <a class="header-anchor" href="#subsequent-automatic-publication" aria-label="Permalink to &quot;Subsequent automatic publication&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/.github/workflows/ci.yml" target="_blank" rel="noreferrer">CI</a> selects checks by changed paths: tooling and documentation for docs, the backend course for teaching sources, and relevant client checks for client changes. <code>verify</code> aggregates all selected jobs; failures and unexpected skips prevent success. The documentation job preserves the checked website artifact. On <code>main</code>, publication requires both successful <code>verify</code> and documentation jobs, pushes that same artifact to <code>gh-pages</code>, then requests a Pages build with <code>contents: write</code> and <code>pages: write</code>. Commits without a website artifact do not publish documentation.</p><p>An Actions <code>GITHUB_TOKEN</code> push does not automatically trigger a Pages build, so keep <code>--request-build</code>. The publishing job does not implicitly change the administrator&#39;s one-time Pages settings.</p><h2 id="verify-and-recover-from-failures" tabindex="-1">Verify and recover from failures <a class="header-anchor" href="#verify-and-recover-from-failures" aria-label="Permalink to &quot;Verify and recover from failures&quot;">​</a></h2><p>Open <code>https://&lt;owner&gt;.github.io/&lt;repository&gt;/</code> and verify bilingual counterparts, search, your chapter, source revision and links. Run <code>just e2e-docs</code> against static artifacts before navigation/base changes; API, databases and Electron are unnecessary.</p><table tabindex="0"><thead><tr><th>Failure</th><th>Recovery</th></tr></thead><tbody><tr><td>Artifact repository/revision mismatch</td><td>Confirm repository/origin and intended commit, then rebuild</td></tr><tr><td>Pages configuration mismatch</td><td>Select branch publishing from <code>gh-pages:/</code>, then request again</td></tr><tr><td>Permission or build failure</td><td>Check CLI/CI permissions and Pages errors; preserve failure output</td></tr><tr><td>Page/asset 404</td><td>Align actual path and DOCS_BASE, fix source and rebuild/publish</td></tr><tr><td>Return to older content</td><td>Check out a reviewed old revision and rebuild/publish instead of editing static pages</td></tr></tbody></table><p>Use <a href="./../tutorials/public-site">static-site maintenance</a> to add links for delivered product capabilities. Backend deployment and recovery are separate tasks in the <a href="./../tutorials/single-machine-production">production guide</a>.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/getting-started/publish-docs.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,26)])])}const b=t(n,[["render",o]]);export{u as __pageData,b as default};
